ENV = dict(os.environ, GOFLAGS="-mod=mod", GOTOOLCHAIN="local", CGO_ENABLED="0", GOPROXY="off")

def verdict(side, cases):
    style = [c for c in cases if c[0].startswith("style:")]
    plain = [c for c in cases if not c[0].startswith("style:")]
    if not cases:
        return "harness produced no cases"
    if side == "after":
        bad = [c[0] for c in cases if not c[1]]
        return "failed %s" % bad if bad else None
    bad = [c[0] for c in plain if not c[1]]
    if bad:
        return "before fails behaviour %s" % bad
    if all(c[1] for c in style):
        return "before passes every style case"
    return None


def stage(root, stem, side):
    directory = os.path.join(root, ".verify", stem + "__" + side)
    os.makedirs(directory, exist_ok=True)
    sources = {
        "solution.go": os.path.join(root, side, stem + ".go"),
        "harness.go": os.path.join(root, "harnesses", stem + ".go"),
        "prelude.go": os.path.join(root, "..", "prelude.go"),
    }
    for name, path in sources.items():
        with open(path) as source, open(os.path.join(directory, name), "w") as target:
            target.write(source.read().rstrip() + "\n")
    with open(os.path.join(directory, "go.mod"), "w") as target:
        target.write("module drill\n\ngo 1.21\n")
    return directory


def check(root, stem, side):
    try:
        directory = stage(root, stem, side)
    except OSError as error:
        return "missing source: %s" % error
    try:
        done = subprocess.run(["go", "run", "."], cwd=directory, env=ENV, capture_output=True, text=True, timeout=60)
    except subprocess.TimeoutExpired:
        return "timed out"
    lines = (done.stdout or "").strip().splitlines()
    try:
        report = json.loads(lines[-1])
    except (IndexError, ValueError):
        return (done.stderr or done.stdout).strip()[-400:]
    if report.get("error"):
        return "error %s" % report["error"]
    cases = [(c["label"], c["passed"]) for c in report.get("cases") or []]
    return verdict(side, cases)


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    stems = sys.argv[1:] or STEMS
    jobs = [(stem, side) for stem in stems for side in ("before", "after")]
    with ThreadPoolExecutor(8) as pool:
        results = list(pool.map(lambda job: check(root, *job), jobs))
    failures = 0
    for (stem, side), why in zip(jobs, results):
        if why:
            failures += 1
            print("FAIL %s [%s] %s" % (stem, side, why))
    print("%d Go refactoring drills checked, %d failures" % (len(stems), failures))
    sys.exit(1 if failures else 0)


main()
